  "root_cause": {
    "category": "config_regression",
    "service": "orders",
    "summary": "Orders lowered the inventory call timeout to 8 ms, causing immediate timeouts and propagating failures to the gateway."
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "Orders configuration key timeout.inventory_ms was changed from 800 ms to 8 ms.",
      "status": "confirmed",
      "cites": ["ops-E0001", "orders-L0002f"]
    },
    {
      "claim": "Immediately after the change, orders client calls to inventory timed out after approximately 8 ms.",
      "status": "confirmed",
      "cites": ["orders-S00ac6"]
    },
    {
      "claim": "Orders responded to its callers with upstream_timeout errors (HTTP 504) due to the inventory timeouts.",
      "status": "confirmed",
      "cites": ["orders-L00034"]
    },
    {
      "claim": "The gateway observed a sustained burst of failed entry requests (HTTP 500 internal_error) as a result of orders' failures.",
      "status": "confirmed",
      "cites": ["gateway-S0071e"]
    }
  ],
  "alternatives": [
    {
      "category": "edge_unreachable",
      "service": "inventory",
      "why_less_likely": "Timeouts match the newly configured low client timeout; inventory's own latency is normal, indicating calls reach inventory but are cut off early.",
      "cites": ["orders-L00030"]
    }
  ],
